body>#yolo-nav{display:block!important;position:sticky!important;top:0!important;z-index:3000!important;min-height:64px;background:#fff!important;border-bottom:1px solid #eee}
#yolo-nav-wrap{max-width:1600px;margin:auto;padding:0 28px;box-sizing:border-box}
#yolo-nav .C6xxU95R{display:block!important;visibility:visible!important}

@media(max-width:700px){#yolo-nav-wrap{padding:0 16px}body>#yolo-nav{min-height:58px}}

#yolo-nav .mtT8rtRR{display:flex!important;align-items:center;gap:22px;flex-shrink:0}
#yolo-nav .mtT8rtRR button{display:flex!important;align-items:center;justify-content:center;width:28px;height:36px;padding:0;border:0;background:transparent;color:#262629;cursor:pointer}
#yolo-nav .mtT8rtRR svg{display:block;width:23px;height:23px;fill:none;stroke:currentColor;stroke-width:1.7;stroke-linecap:round;stroke-linejoin:round}
@media(max-width:700px){#yolo-nav .mtT8rtRR{gap:10px}#yolo-nav .mtT8rtRR button{width:24px}#yolo-nav a.xbEtg3IJ{width:112px!important;flex-basis:112px!important}#yolo-nav .__5rIsrQ9P{gap:4px}}

/* Flat aquarium navigation: no dropdown panels or hover triggers. */
#yolo-nav .__5rIsrQ9P{flex:1;min-width:0;gap:28px}
#yolo-nav .C6xxU95R{min-width:0;flex:1;overflow-x:auto!important;scrollbar-width:none}
#yolo-nav .C6xxU95R::-webkit-scrollbar{display:none}
#yolo-nav ul.offline-nav-links{gap:clamp(12px,1.4vw,24px);width:max-content;overflow:visible}
#yolo-nav .yolo-menu-item{flex:0 0 auto;list-style:none}
#yolo-nav .yolo-menu-item button{display:block;height:64px;padding:0;border:0;background:transparent;color:#262629;font-family:inherit;font-size:14px;font-weight:500;white-space:nowrap;cursor:pointer}
#yolo-nav .yolo-menu-item button:hover{color:#666}
#yolo-nav .mtT8rtRR{margin-left:24px}
@media(max-width:1100px){#yolo-nav .__5rIsrQ9P{gap:20px}#yolo-nav ul.offline-nav-links{gap:18px}}
@media(max-width:700px){#yolo-nav-wrap{flex-wrap:wrap}#yolo-nav .__5rIsrQ9P{display:contents!important}#yolo-nav a.xbEtg3IJ{margin:18px 0}#yolo-nav .C6xxU95R{order:3;flex:0 0 100%;width:100%}#yolo-nav .yolo-menu-item button{height:44px}#yolo-nav .mtT8rtRR{margin-left:auto}}

